#include <bits/stdc++.h>
#include <boost/multiprecision/cpp_int.hpp>
using namespace std;
using boost::multiprecision::cpp_int;
using I = __int128_t;
long long best;
vector<long long> d, g;

I ab(I x) {
    return x < 0 ? -x : x;
}
I floorDiv(I a, I b) {
    I q = a / b, r = a % b;
    if (r < 0)
        q--;
    return q;
}
I ceilDiv(I a, I b) {
    return -floorDiv(-a, b);
}

long long eg(long long a, long long b, long long &x, long long &y) {
    if (!b) {
        x = 1;
        y = 0;
        return a;
    }
    long long u, v, r = eg(b, a % b, u, v);
    x = v;
    y = u - (a / b) * v;
    return r;
}

I two(long long a, long long b, I r) {
    long long x, y, h = eg(a, b, x, y);
    if (r % h)
        return (I)1 << 100;
    I u = (I)x * (r / h), v = (I)y * (r / h), A = a / h, B = b / h, ans = (I)1 << 100;
    I roots[] = {floorDiv(-u, B), floorDiv(v, A), 0};
    for (I t : roots)
        for (int z = -1; z <= 1; z++) {
            I k = t + z;
            ans = min(ans, ab(u + k * B) + ab(v - k * A));
        }
    return ans;
}


// All monetary products and interval endpoints are calculated in signed 128 bits.
struct APContext { long long a=0,b=0,h=0,scale=1,inverse=0; };
APContext prepareAP(long long a,long long b,long long h){
    long long scale=std::gcd(a,h);
    a/=scale; b/=scale; h/=scale;
    long long inverse=0;
    if(h>1){long long y;eg(a,h,inverse,y);inverse%=h;if(inverse<0)inverse+=h;}
    return {a,b,h,scale,inverse};
}
bool feasibleAP(const APContext &p,I x,long long K){
    if(K<0)return false;
    x=ab(x);
    if(x%p.scale)return false;
    x/=p.scale;
    I width=(I)p.b-p.a, sum=(I)p.a+p.b;
    I lo=max(-(I)K,ceilDiv(2*x-width*K,sum));
    I hi=min((I)K,floorDiv(2*x+width*K,sum));
    if(lo>hi)return false;
    I residue=(x%p.h)*p.inverse%p.h,step=p.h;
    if(p.h&1){if((residue-K)%2!=0)residue+=p.h;step*=2;}
    else if((residue-K)%2!=0)return false;
    return residue+ceilDiv(lo-residue,step)*step<=hi;
}
// Returns the exact minimum <= upper, or upper+1 if no such representation exists.
long long minimumAP(const APContext &p,I x,long long upper){
    long long answer=upper+1;
    for(long long parity=0;parity<2;parity++){
        if(upper<parity)continue;
        long long last=upper-((upper-parity)&1);
        if(!feasibleAP(p,x,last))continue;
        long long lo=0,hi=(last-parity)/2;
        while(lo<hi){long long mid=lo+(hi-lo)/2;
            if(feasibleAP(p,x,parity+2*mid))hi=mid;else lo=mid+1;
        }
        answer=min(answer,parity+2*lo);
    }
    return answer;
}
vector<APContext> apContexts;
vector<char> fullAP;

void dfs(int i, I r, long long used) {
    r = ab(r);
    if (!r) {
        best = min(best, used);
        return;
    }
    if (used >= best || r % g[i] || used + ceilDiv(r, d[i]) >= best)
        return;
    int k = d.size() - i;
    if (k == 1) {
        if (r % d[i] == 0 && used + r / d[i] < best)
            best = used + (long long)(r / d[i]);
        return;
    }
    if (k == 2) {
        I z = two(d[i], d[i + 1], r) + used;
        if (z < best)
            best = (long long)z;
        return;
    }

long long lower=minimumAP(apContexts[i],r,best-used);
if(lower>=best-used)return;
if(fullAP[i]){best=used+lower;return;}

long long B=best-used-1;
    I lo = max((I)-B, ceilDiv(r - (I)B * d[i + 1], d[i])),
      hi = min((I)B, floorDiv(r + (I)B * d[i + 1], d[i]));
    long long h = gcd(d[i], g[i + 1]);
    if (r % h)
        return;
    long long step = g[i + 1] / h, res = 0;
    if (step > 1) {
        long long x, y;
        eg(d[i] / h, step, x, y);
        res = (long long)(((r / h) % step * x) % step);
        if (res < 0)
            res += step;
    }
    I first = res + ceilDiv(lo - res, step) * step,
      last = res + floorDiv(hi - res, step) * step;
    if (first > last)
        return;
    I mid = res + floorDiv(r / d[i] - res, step) * step;
    mid = max(first, min(last, mid));
    for (I dist = 0;; dist += step) {
        bool any = false;
        I cs[] = {mid + dist, mid - dist};
        for (int z = 0; z < 2; z++) {
            if (z && dist == 0)
                continue;
            I c = cs[z];
            if (c < first || c > last)
                continue;
            any = true;
            I cost = ab(c);
            if (used + cost >= best)
                continue;
            I rem = r - c * d[i];
            if (used + cost + ceilDiv(ab(rem), d[i + 1]) >= best)
                continue;
            dfs(i + 1, rem, used + (long long)cost);
        }
        if (!any && mid + dist > last && mid - dist < first)
            break;
    }
}

int main() {
    long long x, a, h = 0;
    cin >> x;
    while (cin >> a) {
        d.push_back(a);
        h = gcd(h, a);
    }
    x /= h;
    for (auto &v : d)
        v /= h;
    sort(d.rbegin(), d.rend());
    d.erase(unique(d.begin(), d.end()), d.end());
    best = 2 * d[0] + x / d[0] + 1;
    for (long long a : d)
        if (x % a == 0)
            best = min(best, x / a);
    for (int i = 0; i < (int)d.size(); i++)
        for (int j = 0; j < i; j++) {
            I z = two(d[i], d[j], x);
            if (z < best)
                best = (long long)z;
        }
    g.resize(d.size());
    for (int i = d.size() - 1; i >= 0; i--)
        g[i] = i + 1 == (int)d.size() ? d[i] : gcd(d[i], g[i + 1]);

apContexts.resize(d.size());fullAP.assign(d.size(),false);
long long apStep=0,apMin=d.back();
for(int i=(int)d.size()-1;i>=0;i--){
    apStep=std::gcd(apStep,d[i]-apMin);
    if(apStep>0){
        apContexts[i]=prepareAP(apMin,d[i],apStep);
        fullAP[i]=(d[i]-apMin)/apStep+1==(long long)d.size()-i;
    }
}

dfs(0,x,0);
    cout << best << '\n';
}
